function redactPII(record) {
  if (!record) return record;
  const r = { ...record };
  if (r.ssn) r.ssn = 'XXX-XX-XXXX';
  if (r.dob) r.dob = null;
  if (r.phone) r.phone = r.phone.replace(/\d(?=\d{4})/g, '*');
  return r;
}
